using McpDotNet.Server;
using System.Text.Json.Serialization;

[McpServer("enterprise-nexus-prompts")]
public class PromptTemplateServer : McpServer
{
    // Define a code review prompt template with dynamic parameters
    [McpPrompt("code-review", "Code review prompt for .NET code quality")]
    public async Task<McpPrompt> GetCodeReviewPrompt(
        [McpPromptArgument("code")] string code,
        [McpPromptArgument("language")] string language = "csharp",
        [McpPromptArgument("strictness")] string strictness = "moderate")
    {
        var strictnessLevel = strictness switch
        {
            "strict" => "Critically review all code quality, security, and performance issues.",
            "moderate" => "Review for common issues in code quality and maintainability.",
            "light" => "Provide a light review focusing on obvious issues.",
            _ => "Provide a balanced code review"
        };

        return new McpPrompt
        {
            Messages = new[]
            {
                new McpPromptMessage
                {
                    Role = McpRole.System,
                    Content = $"{strictnessLevel} You are an expert {language} engineer."
                },
                new McpPromptMessage
                {
                    Role = McpRole.User,
                    Content = $"Review the following {language} code:\n\n```\n{code}\n```\n\nRespond with: 1) Summary of issues found, 2) Specific fixes with code examples, 3) Overall rating (1-5 stars)."
                }
            },
            // Declare the arguments for discovery
            Arguments = new[]
            {
                new PromptArgument { Name = "code", Description = "The source code to review", Required = true },
                new PromptArgument { Name = "language", Description = "Programming language", Required = false },
                new PromptArgument { Name = "strictness", Description = "Review strictness level", Required = false }
            }
        };
    }

    // Template with conversation history context
    [McpPrompt("summarize-conversation", "Summarize conversation history")]
    public McpPrompt GetConversationSummary(
        [McpPromptArgument("history")] string conversationHistory,
        [McpPromptArgument("max_length")] int maxLength = 300)
    {
        return new McpPrompt
        {
            Messages = new[]
            {
                new McpPromptMessage
                {
                    Role = McpRole.User,
                    Content = $"Summarize the following conversation in under {maxLength} words, highlighting decisions made, action items, and outstanding questions:\n\n{conversationHistory}\n\nSummary:"
                }
            }
        };
    }
}

public class ContextualPromptEngine
{
    private readonly Dictionary<string, McpPrompt> _templates;

    public McpPrompt RenderTemplate(string templateName, Dictionary<string, object> context)
    {
        var template = _templates[templateName];

        // Resolve conditional logic in templates
        var renderedMessages = template.Messages.Select(m =>
        {
            var content = m.Content;

            // Variable interpolation
            content = Interpolate(content, context);

            // Conditional blocks: {{#if isProduction}}...{{/if}}
            content = ApplyConditionals(content, context);

            // Loop blocks: {{#each items}}...{{/each}}
            content = ApplyLoops(content, context);

            return new McpPromptMessage
            {
                Role = m.Role,
                Content = content
            };
        }).ToList();

        return new McpPrompt { Messages = renderedMessages };
    }

    private string Interpolate(string content, Dictionary<string, object> context)
    {
        foreach (var kvp in context)
        {
            content = content.Replace($"{{{{{kvp.Key}}}}}", kvp.Value?.ToString() ?? "");
        }
        return content;
    }
}
